#![cfg(unix)]
use moloch_live_runtime::{dispatch::DispatchLog,fundamental_policy::{ReviewFile,SourceFile},paper5_runtime::*,value_surface::{mapping_sha256,sha256}};
use serde_json::{json,Value};
use std::collections::{BTreeMap,BTreeSet};
#[path="support/value_surface_fixture.rs"]mod support;
use support::*;
fn save(f:&F,name:&str,bytes:&[u8])->SourceFile{let path=f.root.join(name);std::fs::write(&path,bytes).unwrap();SourceFile{path,sha256:sha256(bytes)}}
fn settings(f:&F)->Settings{
 let artifact=save(f,"atlas.json",&f.bytes);let authority=save(f,"approval.json",&serde_json::to_vec(&json!({"version":1,"trustedReviewSha256":f.trusted_reviews})).unwrap());
 let bindings=(0..5).map(|i|{let review=save(f,&format!("review-{i}.json"),&serde_json::to_vec(&f.reviews[i]).unwrap());let source_files=f.originals[i].iter().enumerate().map(|(j,b)|save(f,&format!("source-{i}-{j}.bin"),b)).collect();let mapping=save(f,&format!("mapping-{i}.json"),&serde_json::to_vec(&f.mappings[i]).unwrap());BindingFiles{review:ReviewFile{path:review.path,file_sha256:review.sha256,source_files},mapping}}).collect();
 Settings{version:1,approved_artifact_sha256:[artifact.sha256.clone()].into(),artifact,authority_path:authority.path,authority_sha256:authority.sha256,approved_mapping_sha256:f.mappings.iter().map(|m|mapping_sha256(m).unwrap()).collect(),bindings,router:RouterSettings{strategy_sha256:"a".repeat(64),order_lifetime_ms:30000,model_uncertainty_per_share:1000,terminal_tail_charge_per_share:1000,write_charge_per_order:100,capital_charge_per_million_unit_ms:0},curve:Some(moloch_live_runtime::election_curve::FitPolicy{factor_id:"national".into(),minimum_races:3,maximum_depth_weight:20,maximum_factor_abs:3.,minimum_residual_micros:10000}),hedges:Some(moloch_live_runtime::election_curve::HedgeLimits{maximum_quantity_per_leg:20,maximum_gross_funding:100000000,maximum_absolute_factor_exposure:0,minimum_model_gain:1,tail_probability_ppm:50000,maximum_tail_loss:0}),allow_research_diagnostics:true,maximum_proposals:32,maximum_semantic_receipt_age_ms:60000,maximum_dispatch_records:20000,maximum_bank_sequence:1_000_000,execution:None}
}
fn nodes(f:&F)->BTreeMap<String,baal_transport_service::Receipt>{f.receipts.iter().enumerate().map(|(i,r)|((101+i).to_string(),r.clone())).collect()}
fn evaluate(r:&Runtime,f:&F,log:&DispatchLog,at:u64)->Diagnostic{r.evaluate(&f.bank,&f.scope,log,&nodes(f),&BTreeMap::new(),&BTreeSet::new(),at)}
#[test]fn real_session_retained_sources_flow_through_surface_curve_and_router_without_money_changes(){let f=F::new();let cfg=settings(&f);let r=Runtime::load(&cfg).unwrap();let log=DispatchLog::open(&f.root.join("p5-dispatch.ndjson")).unwrap();let head=f.bank.durable_head();let financial=f.bank.engine().report().unwrap();let out=evaluate(&r,&f,&log,NOW);assert_eq!(out.state,"proposal_only");assert_eq!(out.routing.len(),5);assert!(out.routing.iter().any(|r|r["candidates"].as_array().unwrap().len()==3));assert!(out.curve.is_some());assert_eq!(out.hedge_ideas.len(),1);assert!(!out.execution_authority);assert!(!out.financial_state_changed);assert_eq!(out.source_files_read_during_evaluation,0);assert_eq!(f.bank.durable_head(),head);assert_eq!(f.bank.engine().report().unwrap(),financial);}
#[test]fn originals_are_cached_after_verified_setup_and_no_evaluation_source_file_reads_occur(){let f=F::new();let cfg=settings(&f);let r=Runtime::load(&cfg).unwrap();let hashes=r.original_source_hashes().clone();std::fs::remove_file(&cfg.artifact.path).unwrap();std::fs::remove_file(&cfg.authority_path).unwrap();for b in &cfg.bindings{std::fs::remove_file(&b.review.path).unwrap();std::fs::remove_file(&b.mapping.path).unwrap();for s in &b.review.source_files{std::fs::remove_file(&s.path).unwrap();}}let log=DispatchLog::open(&f.root.join("p5-dispatch.ndjson")).unwrap();let out=evaluate(&r,&f,&log,NOW);assert_eq!(out.state,"proposal_only");assert_eq!(out.source_files_read_during_evaluation,0);assert_eq!(r.original_source_hashes(),&hashes);assert!(!out.execution_authority,"cached proposal facts never replace final source/physical authority guards");}
#[test]fn research_and_expired_original_source_qualifications_are_honest_without_reactivation(){let f=F::new();let mut cfg=settings(&f);cfg.allow_research_diagnostics=false;let r=Runtime::load(&cfg).unwrap();let log=DispatchLog::open(&f.root.join("p5-dispatch.ndjson")).unwrap();let out=evaluate(&r,&f,&log,NOW);assert_eq!(out.state,"unavailable");assert_eq!(out.deferred[0]["reason"],"research_model_not_promoted");assert!(out.routing.is_empty());cfg.allow_research_diagnostics=true;let r=Runtime::load(&cfg).unwrap();let out=evaluate(&r,&f,&log,NOW+120000);assert_eq!(out.deferred[0]["reason"],"posterior_expired_original_clock");assert!(out.routing.is_empty());}
#[test]fn unknown_original_dispatch_blocks_proposals_without_becoming_zero_or_closed(){let f=F::new();let r=Runtime::load(&settings(&f)).unwrap();let mut log=DispatchLog::open(&f.root.join("p5-dispatch.ndjson")).unwrap();log.append(json!({"kind":"intent","qid":9000,"spec":{"method":"POST","endpoint":"/orders","body":{"tournamentId":"cup","exchangeId":"101","side":"yes","action":"buy","quantity":1,"price":0.4},"bodyJson":"{\"tournamentId\":\"cup\",\"exchangeId\":\"101\",\"side\":\"yes\",\"action\":\"buy\",\"quantity\":1,\"price\":0.4}"},"at":iso(NOW)})).unwrap();log.append(json!({"kind":"attempt","qid":9000,"at":iso(NOW),"captureAtMs":NOW,"nativeHead":f.bank.durable_head()})).unwrap();let out=evaluate(&r,&f,&log,NOW);assert_eq!(out.state,"deferred");assert!(out.routing.is_empty());assert!(!log.never_attempted(9000));assert!(!log.closed.contains(&9000));}
#[test]fn missing_or_changed_current_node_never_causes_a_new_api_read_or_foreign_mapping(){let f=F::new();let r=Runtime::load(&settings(&f)).unwrap();let log=DispatchLog::open(&f.root.join("p5-dispatch.ndjson")).unwrap();let out=r.evaluate(&f.bank,&f.scope,&log,&BTreeMap::new(),&BTreeMap::new(),&BTreeSet::new(),NOW);assert_eq!(out.state,"unavailable");assert_eq!(out.deferred.len(),5);assert!(out.routing.is_empty());let mut n=nodes(&f);n.get_mut("104").unwrap().data["root"]["contract_id"]=json!("other");let out=r.evaluate(&f.bank,&f.scope,&log,&n,&BTreeMap::new(),&BTreeSet::new(),NOW);assert!(out.routing.is_empty());assert!(out.deferred.iter().any(|d|d["reason"]=="SURFACE_CURRENT_CONTRACT_CHANGED"));assert_eq!(out.source_files_read_during_evaluation,0);}
#[test]fn original_source_tampering_and_unapproved_mapping_fail_at_setup(){let f=F::new();let mut cfg=settings(&f);std::fs::write(&cfg.bindings[0].review.source_files[1].path,b"changed original source").unwrap();assert!(Runtime::load(&cfg).is_err());cfg=settings(&f);cfg.approved_mapping_sha256.clear();assert!(Runtime::load(&cfg).is_err());cfg=settings(&f);cfg.approved_artifact_sha256.clear();assert!(Runtime::load(&cfg).is_err());}
#[test]fn proposal_count_and_diagnostic_work_bounds_are_enforced_without_native_mutation(){let f=F::new();let mut cfg=settings(&f);cfg.maximum_proposals=2;let r=Runtime::load(&cfg).unwrap();let log=DispatchLog::open(&f.root.join("p5-dispatch.ndjson")).unwrap();let out=evaluate(&r,&f,&log,NOW);let count=out.routing.iter().map(|r|r["candidates"].as_array().unwrap().len()).sum::<usize>()+out.hedge_ideas.len();assert!(count<=2);cfg.maximum_bank_sequence=1;let r=Runtime::load(&cfg).unwrap();let out=evaluate(&r,&f,&log,NOW);assert_eq!(out.deferred[0]["reason"],"diagnostic_work_bound");assert!(out.routing.is_empty());}
#[test]fn typed_settings_reject_unknown_fields_instead_of_treating_them_as_approval(){let f=F::new();let cfg=settings(&f);let mut v:Value=serde_json::to_value(cfg).unwrap();v["activate"]=json!(true);assert!(serde_json::from_value::<Settings>(v).is_err());}
#[test]fn retained_semantic_root_age_does_not_rewrite_current_book_age_or_physical_packet(){let mut f=F::new();let cfg=settings(&f);let r=Runtime::load(&cfg).unwrap();let log=DispatchLog::open(&f.root.join("p5-dispatch.ndjson")).unwrap();for i in 0..5{f.book(i,NOW+20000,if i<3{"0.490000"}else{"0.350000"},if i<3{"0.510000"}else{"0.360000"},20);}let out=evaluate(&r,&f,&log,NOW+20000);assert_eq!(out.state,"proposal_only");assert_eq!(out.source_freshness.len(),5);assert!(out.source_freshness.iter().all(|s|s["semanticReceiptRequestAgeMs"]==20000&&s["bookSourceAgeMs"]==0&&s["physicalPacketStillRequired"]==true));let stale=evaluate(&r,&f,&log,NOW+30001);assert!(stale.routing.is_empty());assert!(stale.deferred.iter().any(|d|d["reason"]=="SURFACE_CURRENT_NATIVE_BOOK_REQUIRED"));}

// All execution qualification below is SYNTHETIC TEST approval, never an
// assertion that the current real research-only Atlas artifact is qualified.
fn qualify_execution_fixture(f:&mut F){
 use moloch_live_runtime::fundamental_policy::review_sha256;
 let mut raw:Value=serde_json::from_slice(&f.bytes).unwrap();raw["qualification"]=json!({"kind":"qualified","reason":"synthetic test-only external approval"});f.bytes=seal(raw);let source=sha256(&f.bytes);
 for i in 0..f.reviews.len(){f.originals[i][0]=f.bytes.clone();f.hashes[i][0]=source.clone();f.reviews[i].sources[0].sha256=source.clone();let review=review_sha256(&f.reviews[i]).unwrap();f.trusted_reviews.insert(review.clone());f.mappings[i].model_source_sha256=source.clone();f.mappings[i].review_sha256=review;f.trusted_mappings.insert(mapping_sha256(&f.mappings[i]).unwrap());}
}
fn execution_nodes(f:&F)->BTreeMap<String,baal_transport_service::Receipt>{let mut ns=nodes(f);for r in ns.values_mut(){r.data["contexts"]=json!([{"type":"tournament","tournament":{"id":f.scope.tournament_id,"slug":f.scope.tournament_slug}}]);}ns}
fn execution_settings(f:&F)->Settings{
 use moloch_live_runtime::{semantic_states::{Review,Contract,Source,State,StateKind,PayoutRule},probabilistic_portfolio::PolicyInput};
 let mut cfg=settings(f);let original_nodes=execution_nodes(f);let mut sources=Vec::new();let mut contracts=Vec::new();
 for(i,input)in f.reviews.iter().enumerate(){let r=&original_nodes[&input.exchange_id];let src=save(f,&format!("semantic-node-{i}.json"),&serde_json::to_vec(r).unwrap());contracts.push(Contract{market_id:input.market_id.clone(),exchange_id:input.exchange_id.clone(),contract_id:input.contract_id.clone(),official_root_sha256:input.official_contract_root_sha256.clone(),original_node_sha256:src.sha256.clone(),predicate:"Explicit synthetic reviewed ordinary party predicate".into(),unresolved_exceptions:vec!["Synthetic test source, not actual resolver completeness".into()]});sources.push(src);}
 let bound=f.bound(NOW).unwrap();let states=bound.scenarios().iter().map(|s|State{id:s.id.clone(),kind:StateKind::PartyWinner,outcomes:s.payout_micros.iter().enumerate().map(|(i,v)|if (*v==1_000_000)==(bound.contracts()[i].side==moloch_replay::Side::Yes){PayoutRule::ResolvedYes}else{PayoutRule::ResolvedNo}).collect(),source_sha256:sources.iter().map(|s|s.sha256.clone()).collect(),assumption_label:"Explicit synthetic ordinary state mapping; no exceptional guarantee".into()}).collect();
 let semantic=Review{version:1,review_id:"paper5-context-fixture".into(),run_id:"surface-fixture".into(),bank_manifest_sha256:f.bank.manifest_hash().as_str().unwrap().into(),tournament_id:f.scope.tournament_id.clone(),tournament_slug:f.scope.tournament_slug.clone(),scenario_source_sha256:sha256(&f.bytes),reviewed_at_ms:NOW,valid_until_ms:NOW+100000,contracts,states,sources:sources.iter().map(|s|Source{sha256:s.sha256.clone(),observed_at_ms:NOW,maximum_age_ms:120000}).collect(),excluded_states:vec!["Exceptional outcomes not certified complete".into()],probabilities_are_reviewed_assumptions:true,exception_weights_ppm:BTreeMap::new()};
 let semantic=save(f,"semantic-review.json",&serde_json::to_vec(&semantic).unwrap());let policy=PolicyInput{version:1,run_id:"surface-fixture".into(),bank_manifest_sha256:f.bank.manifest_hash().as_str().unwrap().into(),valid_until_ms:NOW+100000,quantities:vec![5],maximum_enumerations:10000,maximum_gross_buy_cost:10_000_000,minimum_expected_gain:1,maximum_incremental_cvar_loss:20_000_000,maximum_terminal_cvar_loss:20_000_000,tail_ppm:100000,capital_rate_ppm_per_day:0,fee_per_share:0,maximum_book_age_ms:10000,maximum_plan_age_ms:5000,factors:BTreeMap::new()};let policy=save(f,"risk-policy.json",&serde_json::to_vec(&policy).unwrap());
 cfg.execution=Some(ExecutionSettings{version:1,approved_semantic_review_sha256:[semantic.sha256.clone()].into(),semantic_review:semantic,semantic_sources:sources,approved_risk_policy_sha256:[policy.sha256.clone()].into(),risk_policy:policy});cfg
}
fn rewrite_execution_file(f:&F,cfg:&mut Settings,semantic:bool,change:impl FnOnce(&mut Value)){
 let e=cfg.execution.as_mut().unwrap();let source=if semantic{&mut e.semantic_review}else{&mut e.risk_policy};let mut v:Value=serde_json::from_slice(&std::fs::read(&source.path).unwrap()).unwrap();change(&mut v);let b=serde_json::to_vec(&v).unwrap();*source=save(f,if semantic{"semantic-revised.json"}else{"policy-revised.json"},&b);if semantic{e.approved_semantic_review_sha256.insert(source.sha256.clone());}else{e.approved_risk_policy_sha256.insert(source.sha256.clone());}
}
#[test]fn genuine_cached_approved_sources_create_opaque_optimizer_context_without_reservation(){let mut f=F::new();qualify_execution_fixture(&mut f);let cfg=execution_settings(&f);let runtime=Runtime::load(&cfg).unwrap();let log=DispatchLog::open(&f.root.join("execution-dispatch.ndjson")).unwrap();let head=f.bank.durable_head();let report=f.bank.engine().report().unwrap();let context=runtime.execution_context(&f.bank,&f.scope,&log,&execution_nodes(&f),NOW).unwrap();assert_eq!(context.surface().contracts().len(),5);assert_eq!(context.semantics().scenario_source_sha256(),runtime.source_sha256());assert_eq!(context.policy().sha256(),cfg.execution.as_ref().unwrap().risk_policy.sha256);let plan=context.optimize(&f.bank,&f.scope,&log,NOW).unwrap().unwrap();assert_eq!(plan.legs().len(),2);let reservation=plan.qualified_reservation(&f.bank,&log,&f.scope,context.surface(),context.semantics(),context.policy(),NOW).unwrap();reservation.validate_plan(&plan).unwrap();assert_eq!(reservation.event()["type"],"probabilistic_portfolio_reserve_v1");assert_eq!(f.bank.durable_head(),head);assert_eq!(f.bank.engine().report().unwrap(),report);assert!(f.bank.engine().package_records().as_array().unwrap().is_empty());}
#[test]fn research_diagnostic_permission_and_diagnostic_json_cannot_mint_execution_context(){let f=F::new();let cfg=execution_settings(&f);let runtime=Runtime::load(&cfg).unwrap();let log=DispatchLog::open(&f.root.join("execution-dispatch.ndjson")).unwrap();assert!(cfg.allow_research_diagnostics);assert_eq!(evaluate(&runtime,&f,&log,NOW).state,"proposal_only");assert_eq!(runtime.execution_context(&f.bank,&f.scope,&log,&execution_nodes(&f),NOW).err().unwrap().to_string(),"P5_EXECUTION_RESEARCH_MODEL");let none=Runtime::load(&settings(&f)).unwrap();assert_eq!(none.execution_context(&f.bank,&f.scope,&log,&execution_nodes(&f),NOW).err().unwrap().to_string(),"P5_EXECUTION_NOT_CONFIGURED");}
#[test]fn execution_setup_rejects_unapproved_tampered_or_mismatched_semantic_and_policy_originals(){for case in ["semantic_approval","risk_approval","semantic_source","policy_source","semantic_set","semantic_model","policy_run","policy_bank"]{let mut f=F::new();qualify_execution_fixture(&mut f);let mut cfg=execution_settings(&f);match case{
 "semantic_approval"=>cfg.execution.as_mut().unwrap().approved_semantic_review_sha256.clear(),"risk_approval"=>cfg.execution.as_mut().unwrap().approved_risk_policy_sha256.clear(),"semantic_source"=>std::fs::write(&cfg.execution.as_ref().unwrap().semantic_sources[0].path,b"changed original").unwrap(),"policy_source"=>std::fs::write(&cfg.execution.as_ref().unwrap().risk_policy.path,b"changed original").unwrap(),"semantic_set"=>rewrite_execution_file(&f,&mut cfg,true,|v|{v["contracts"].as_array_mut().unwrap().pop();for row in v["states"].as_array_mut().unwrap(){row["outcomes"].as_array_mut().unwrap().pop();}}),"semantic_model"=>rewrite_execution_file(&f,&mut cfg,true,|v|v["scenarioSourceSha256"]=json!("f".repeat(64))),"policy_run"=>rewrite_execution_file(&f,&mut cfg,false,|v|v["runId"]=json!("different-run")),_=>rewrite_execution_file(&f,&mut cfg,false,|v|v["bankManifestSha256"]=json!("f".repeat(64)))}assert!(Runtime::load(&cfg).is_err(),"{case}");}}
#[test]fn execution_requires_current_exact_full_semantic_set_and_actual_tournament_body(){let mut f=F::new();qualify_execution_fixture(&mut f);let runtime=Runtime::load(&execution_settings(&f)).unwrap();let log=DispatchLog::open(&f.root.join("execution-dispatch.ndjson")).unwrap();for case in ["missing","changed_root","foreign_endpoint","body_tid","missing_body","scope"]{let mut n=execution_nodes(&f);let mut scope=f.scope.clone();match case{"missing"=>{n.remove("101");},"changed_root"=>n.get_mut("101").unwrap().data["root"]["contract_id"]=json!("999"),"foreign_endpoint"=>n.get_mut("101").unwrap().endpoint="/markets/201/nodes?tournamentId=foreign".into(),"body_tid"=>n.get_mut("101").unwrap().data["contexts"][0]["tournament"]["id"]=json!("foreign"),"missing_body"=>{n.get_mut("101").unwrap().data.as_object_mut().unwrap().remove("contexts");},_=>scope.tournament_id="foreign".into()}assert!(runtime.execution_context(&f.bank,&scope,&log,&n,NOW).is_err(),"{case}");}}
#[test]fn context_caches_sources_but_never_renews_model_node_book_or_policy_clocks(){let mut f=F::new();qualify_execution_fixture(&mut f);let cfg=execution_settings(&f);let runtime=Runtime::load(&cfg).unwrap();let log=DispatchLog::open(&f.root.join("execution-dispatch.ndjson")).unwrap();let nodes=execution_nodes(&f);let context=runtime.execution_context(&f.bank,&f.scope,&log,&nodes,NOW).unwrap();std::fs::remove_file(&cfg.execution.as_ref().unwrap().risk_policy.path).unwrap();std::fs::remove_file(&cfg.execution.as_ref().unwrap().semantic_review.path).unwrap();context.validate_current(&f.bank,&f.scope,&log,NOW+1).unwrap();assert!(context.validate_current(&f.bank,&f.scope,&log,NOW+10001).is_err());assert!(runtime.execution_context(&f.bank,&f.scope,&log,&nodes,NOW+10001).is_err());assert!(runtime.execution_context(&f.bank,&f.scope,&log,&nodes,NOW+120000).is_err());}
#[test]fn context_rejects_bank_and_dispatch_mutation_before_any_financial_event(){let mut f=F::new();qualify_execution_fixture(&mut f);let runtime=Runtime::load(&execution_settings(&f)).unwrap();let mut log=DispatchLog::open(&f.root.join("execution-dispatch.ndjson")).unwrap();let context=runtime.execution_context(&f.bank,&f.scope,&log,&execution_nodes(&f),NOW).unwrap();log.append(json!({"kind":"intent","qid":9000,"spec":{"method":"POST","endpoint":"/orders","body":{"tournamentId":"cup","exchangeId":"101","side":"yes","action":"buy","quantity":1,"price":0.4},"bodyJson":"{}"},"at":iso(NOW)})).unwrap();assert!(context.validate_current(&f.bank,&f.scope,&log,NOW).is_err());drop(log);let log=DispatchLog::open(&f.root.join("different-dispatch.ndjson")).unwrap();let context=runtime.execution_context(&f.bank,&f.scope,&log,&execution_nodes(&f),NOW).unwrap();f.book(0,NOW+1,"0.480000","0.510000",20);assert!(context.validate_current(&f.bank,&f.scope,&log,NOW+1).is_err());}
#[test]fn absent_execution_settings_preserve_original_settings_serialization(){let f=F::new();let cfg=settings(&f);let raw=serde_json::to_value(&cfg).unwrap();assert!(raw.get("execution").is_none());let round:Settings=serde_json::from_value(raw.clone()).unwrap();assert!(round.execution.is_none());assert_eq!(serde_json::to_value(round).unwrap(),raw);}
